    //   int getLevel()
    //   int getCycles()
    //   boolean isLow()
}
```

parts.model_answer:
One correct implementation (ALTON reference answer):
```java
public class Battery {
    private int level;
    private int cycles;

    public Battery(int startLevel) {
        level = startLevel;
        cycles = 0;
    }
    public int use(int amount) {
        int used = amount;
        if (used > level) {
            used = level;
        }
        level -= used;
        return used;
    }
    public void recharge() {
        level = 100;
        cycles++;
    }
    public int getLevel() {
        return level;
    }
    public int getCycles() {
        return cycles;
    }
    public boolean isLow() {
        return level < 20;
    }
}
```

